func encResponseMetadata(out []byte, v *ResponseMetadata, depth int) []byte {
	out = append(out, '{')
	first := true
	if v.Code != "" {
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "code")
		out = append(out, ':', ' ')
		out = esc(out, v.Code)
	}
	if v.Error != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "error")
		out = append(out, ':', ' ')
		out = esc(out, v.Error)
	}
	if v.Secret != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "secret")
		out = append(out, ':', ' ')
		out = esc(out, v.Secret)
	}
	if v.Token != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "token")
		out = append(out, ':', ' ')
		out = esc(out, v.Token)
	}
	if v.Expires != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "expires")
		out = append(out, ':', ' ')
		out = esc(out, v.Expires)
	}
	if v.App != nil {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "app")
		out = append(out, ':', ' ')
		out = encAppMetadata(out, v.App, depth+1)
	}
	if v.Right != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "right")
		out = append(out, ':', ' ')
		out = esc(out, v.Right)
	}
	if len(v.Apps) != 0 {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "apps")
		out = append(out, ':', ' ')
		out = encList(out, v.Apps, depth+1, encAppMetadata)
	}
	if len(v.Holds) != 0 {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "holds")
		out = append(out, ':', ' ')
		out = encList(out, v.Holds, depth+1, encHoldMetadata)
	}
	if !first {
		out = append(out, '\n')
		out = pad(out, depth)
	}
	return append(out, '}')
}

